// Synthetic, memory-only UI specimen. No network requests, credentials or actual health data.
const main = document.querySelector('main');
const scenario = document.querySelector('#scenario');
const model = { draft: null, active: null, revision: 0, metric: 'hr' };
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge = (s) => `<span class="badge">${s}</span>`;
const metric = (name,value,unit) => `<div class="metric"><dt>${name}</dt><dd>${value} <small>${unit}</small></dd></div>`;
const head = (section,title,text) => `<div class="page-head"><div><div class="eyebrow">${section}</div><h1>${title}</h1><p class="secondary">${text}</p></div><button data-refresh>Voorbeeld verversen</button></div>`;
function notice() {
  const messages = {
    ready: ['','✓ Gegevens bijgewerkt om 14:32 · Voorbeeld van 30 september'],
    pending: ['warn','◷ Workout ontvangen om 14:32. De gedeelde coachbeoordeling volgt nog.'],
    stale: ['warn','◷ Laatste gegevens van gisteren, 18:10. Advies moet opnieuw worden beoordeeld.'],
    empty: ['','Nog geen gegevens voor deze periode. Ontbrekende metingen worden niet als nul ingevuld.'],
    error: ['error','! Ophalen mislukt. De vorige gegevens van 14:32 blijven zichtbaar. Probeer opnieuw.'],
  };
  const [kind,text] = messages[scenario.value];
  return `<div class="notice ${kind}" role="status">${text}</div>`;
}
function assessment() {
  if (scenario.value !== 'ready') return `<section class="card"><h2>Coachbeoordeling</h2><p>${scenario.value === 'empty' ? 'Nog geen activiteit om te beoordelen.' : 'Geen actueel vervolgadvies beschikbaar.'}</p><p class="secondary">Je kunt de beschikbare metingen hieronder wel bekijken. Nieuw advies verschijnt hier en bij de activiteit vanuit dezelfde beoordeling.</p></section>`;
  return `<section class="card hero"><div class="meta">${badge('Coachinterpretatie')}<span>Bij deze workout · 14:34</span></div><h2>Je rustige duurloop is afgerond</h2><p>Dit voorbeeld laat zien hoe een korte beoordeling aansluit op de uitgevoerde training. De meetwaarden staan apart; de onderbouwing blijft één stap verder beschikbaar.</p><details><summary>Bekijk de onderbouwing</summary><p>Voorbeeld: uitgevoerd 60 minuten, waarvan 30 minuten in de ingestelde hartslagzone Z2. Dat is een beschrijving van deze zoneverdeling, geen universeel trainingsvoorschrift.</p><p class="hint">Profielversie 2 · Contextversie 3 · Dezelfde beoordeling bij Vandaag en Activiteit.</p></details></section>`;
}
function today() {
  return head('Vandaag','Je dag in één overzicht','Eerst wat er is gebeurd. Daarna wat dat betekent voor je plan.') + notice() +
    (scenario.value === 'empty' ? `<section class="card empty"><h2>Je eerste overzicht begint met gegevens</h2><p>Koppel een bron of bekijk welke bronnen al beschikbaar zijn.</p><a class="button primary" href="#data">Bekijk bronnen</a></section>` : `<div class="grid"><div class="stack"><section class="card"><div class="meta">${badge('✓ Voltooid')}<span>Hardlopen · vandaag 13:20</span></div><h2>Rustige duurloop</h2><dl class="metrics">${metric('Afstand','10,2','km')}${metric('Duur','1:00','uur')}${metric('Gemiddelde hartslag','138','bpm')}</dl><a class="button primary" href="#training">Bekijk je workout</a></section>${assessment()}</div><aside class="stack"><section class="card"><h2>Vandaag en morgen</h2><ul class="timeline"><li><span class="hint">Vandaag · voltooid</span><strong>Rustige duurloop</strong><span>Uitgevoerde activiteit</span></li><li><span class="hint">Morgen · gepland</span><strong>Hersteldag in je plan</strong><span>Plangegeven · nog geen uitvoering</span></li><li><span class="hint">Morgen · agenda</span><strong>Een persoonlijke afspraak</strong><span>Beschikbaarheid, geen gemeten training</span></li></ul></section><section class="card"><h2>Herstel in context</h2><p>Slaapduur <strong>7 u 42 min</strong></p><p class="hint">Apparaatschatting · afgelopen nacht</p><a href="#health">Bekijk herstel en trends</a></section></aside></div>`);
}
const zones = {
  hr: {name:'Hartslag',unit:'bpm',bounds:['< 120','120–139','140–154','155–169','≥ 170'],times:[10,30,12,6,2]},
  pace: {name:'Tempo',unit:'min/km',bounds:['> 6:30','5:45–6:30','5:00–5:44','4:20–4:59','< 4:20'],times:[14,26,13,5,2]},
  power: {name:'Vermogen',unit:'W',bounds:['< 160','160–209','210–259','260–309','≥ 310'],times:[8,32,12,6,2]},
};
function zonePanel() {
  const z = zones[model.metric];
  return `<section class="card"><h2>Tijd in zones</h2><label>Meetgrootheid <select id="zone-metric"><option value="hr" ${model.metric==='hr'?'selected':''}>Hartslag</option><option value="pace" ${model.metric==='pace'?'selected':''}>Tempo</option><option value="power" ${model.metric==='power'?'selected':''}>Vermogen</option></select></label><p class="hint">${z.name} · ${z.unit} · fictieve zone-instelling · 60 van 60 minuten beschikbaar</p><div class="zone-chart" role="img" aria-label="${z.name}: Z2 bevat de meeste minuten. Alle waarden staan in de tabel.">${z.times.map((n,i)=>`<div class="zone-row"><strong>Z${i+1}</strong><div class="track"><div class="fill" style="--zone:var(--z${i+1});width:${n/60*100}%"></div></div><span>${n} min</span></div>`).join('')}</div><div class="table-wrap"><table><caption>Zoneverdeling ${z.name.toLowerCase()}</caption><thead><tr><th scope="col">Zone</th><th scope="col">Grens (${z.unit})</th><th scope="col">Tijd</th></tr></thead><tbody>${z.times.map((n,i)=>`<tr><th scope="row"><span class="swatch" style="background:var(--z${i+1})" aria-hidden="true"></span>Z${i+1}</th><td>${esc(z.bounds[i])}</td><td>${n} min</td></tr>`).join('')}</tbody></table></div><p class="hint">Zonenummers beschrijven deze meetgrootheid. Z2 voor tempo is niet automatisch dezelfde belasting als Z2 voor hartslag.</p></section>`;
}
function training() {
  if(scenario.value === 'empty') return head('Training / Activiteit','Nog geen activiteit','Geen metingen beschikbaar voor deze selectie.')+notice()+`<section class="card empty"><h2>Geen zoneverdeling beschikbaar</h2><p>Kies een activiteit met meetgegevens om zones te bekijken.</p><a class="button" href="#data">Bekijk bronnen</a></section>`;
  return head('Training / Activiteit','Rustige duurloop','Fictieve activiteit · 30 september · 13:20–14:20')+notice()+`<div class="grid"><div class="stack"><section class="card"><div class="meta">${badge('✓ Voltooid')}${badge('Metingen')}</div><dl class="metrics">${metric('Afstand','10,2','km')}${metric('Duur','60','min')}${metric('Gem. tempo','5:53','min/km')}</dl><p class="hint">Eén samengevoegde activiteit. Details over bron en correcties staan bij de onderbouwing.</p></section>${zonePanel()}</div><aside class="stack">${assessment()}<section class="card"><h2>Wat telt mee?</h2><p>Een geplande workout en de uitgevoerde activiteit blijven afzonderlijk herkenbaar.</p><details><summary>Bron en gegevensdekking</summary><p>Fictief voorbeeld: 60 minuten hartslag, tempo en vermogen. Geen ontbrekende samples in dit ontwerpvoorbeeld.</p></details></section></aside></div>`;
}
function health() {
  return head('Gezondheid / Slaap','Je laatste nacht','Recente waarde naast persoonlijke context, zonder afgeleid advies te vermommen als meting.')+notice()+`<div class="grid"><section class="card"><div class="meta">${badge('Apparaatschatting')}<span>Afgelopen nacht</span></div><h2>Slaapduur</h2><dl class="metrics">${metric('Deze nacht',scenario.value==='empty'?'—':'7:42','uur')}${metric('7-daags gemiddelde',scenario.value==='empty'?'—':'7:18','uur')}</dl><p>De bron schat slaapduur. Een ontbrekende nacht wordt niet als nul uur meegerekend.</p><a href="#insight">Bekijk de trend met gegevensdekking</a></section><section class="card"><h2>Je eigen ervaring</h2><p>Een check-in vult apparaatmetingen aan met hoe je je voelt.</p><label class="field">Voorbeeldnotitie<textarea placeholder="Bijvoorbeeld hoe uitgerust je je voelt"></textarea></label><button data-note>Voorbeeldnotitie bewaren</button><p class="status-line" role="status" id="note-status"></p></section></div>`;
}
function insight() {
  if(scenario.value === "empty") return head("Inzicht / Trends","Nog geen trend","Voor deze periode zijn geen meetwaarden beschikbaar.")+notice();
  return head('Inzicht / Trends','Begrijp wat er verandert','Elke grafiek benoemt de meetgrootheid, de periode en de beschikbare gegevens.')+notice()+`<section class="card"><h2>Slaapduur · laatste 7 nachten</h2><div class="meta">${badge('Apparaatschatting')}<span>6 van 7 nachten beschikbaar · uren</span></div><div class="chart-scroll" role="region" tabindex="0" aria-label="Slaapgrafiek; horizontaal schuiven op een klein scherm"><svg class="chart" viewBox="0 0 900 220" role="img" aria-label="Slaapduur varieert in het voorbeeld tussen 6,5 en 8,5 uur. Eén nacht ontbreekt. Zie de tabel."><g stroke="var(--line)"><path d="M55 25H865M55 85H865M55 145H865" fill="none"/></g><g><text x="15" y="30">9 u</text><text x="15" y="90">7 u</text><text x="15" y="150">5 u</text></g><g fill="none" stroke="var(--action)" stroke-width="3"><path d="M80 100L205 70L330 55"/><path d="M580 85L705 40L830 64"/></g><g fill="var(--action)">${[[80,100],[205,70],[330,55],[580,85],[705,40],[830,64]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5"/>`).join('')}</g><g text-anchor="middle">${['24 sep','25 sep','26 sep','27 sep','28 sep','29 sep','30 sep'].map((s,i)=>`<text x="${80+i*125}" y="190">${s}</text>`).join('')}<text x="455" y="115">Geen gegevens</text></g></svg></div><details><summary>Bekijk de datatabel</summary><div class="table-wrap"><table><caption>Slaapduur per nacht (fictief)</caption><thead><tr><th scope="col">Datum</th><th scope="col">Uren</th></tr></thead><tbody>${['6,5','7,5','8,0','Geen gegevens','7,0','8,5','7,7'].map((s,i)=>`<tr><th scope="row">${24+i} september</th><td>${s}</td></tr>`).join('')}</tbody></table></div></details><p class="hint">Een onderbroken lijn toont ontbrekende gegevens. Een enkele verandering bewijst geen oorzaak.</p></section>`;
}
function data() {
  return head('Instellingen / Gegevens','Komt alles binnen?','Verbindingsstatus en actualiteit zijn verschillende dingen.')+notice()+`<section class="card"><h2>Je bronnen</h2><div class="source-row"><div><strong>Trainingsbron</strong><p class="hint">Activiteiten en geplande workouts</p></div><div>${badge('✓ Verbonden')}<p>Laatst ontvangen 14:32</p></div><button data-source>Voorbeeld vernieuwen</button></div><div class="source-row"><div><strong>Lichaamsmetingen</strong><p class="hint">Nieuwe metingen verschijnen na ontvangst</p></div><div>${badge('✓ Verbonden')}<p>Laatste meting gisteren 08:15</p></div><button data-source>Voorbeeld vernieuwen</button></div><div class="source-row"><div><strong>Extra activiteitenbron</strong><p class="hint">Alleen deze bron heeft aandacht nodig</p></div><div>${badge('! Opnieuw verbinden')}<p>Laatste succes gisteren 18:10</p></div><button data-reconnect>Bekijk voorbeeldstappen</button></div><div id="source-status" role="status"></div></section>`;
}
const names={balanced:'Gebalanceerde duurtraining',polarized:'Gepolariseerd',pyramidal:'Piramidaal',custom:'Eigen methode',individual:'Individueel',masters:'Masteratleet',consistency:'Duurzaam en consistent',performance:'Prestatie'};
function settings() {
  const p=model.draft||model.active||{method:'balanced',athlete:'individual',priority:'consistency',instructions:''};
  return head('Instellingen / Coach','Eén herkenbare coachaanpak','Je instellingen sturen nieuwe adviezen. Bestaande rapporten behouden hun oorspronkelijke context.')+`<div class="grid"><section class="card"><h2>Je coachprofiel</h2><p class="meta">${badge(model.active?'Actief profiel':'Nog geen actief profiel')}<span>Opgeslagen conceptversie ${model.revision}</span></p><form id="coach-form" novalidate><div id="form-errors"></div><fieldset><legend>Aanpak en prioriteit</legend><div class="form-grid">${[['method','Trainingsmethode',['balanced','polarized','pyramidal','custom']],['athlete','Atleetprofiel',['individual','masters']],['priority','Doelprioriteit',['consistency','performance']]].map(([key,label,opts])=>`<label class="field">${label}<select name="${key}">${opts.map(v=>`<option value="${v}" ${p[key]===v?'selected':''}>${names[v]}</option>`).join('')}</select></label>`).join('')}</div><p class="hint">Masteratleet legt nadruk op individueel herstel en duurzaam presteren. Het is geen vaste beperking op basis van leeftijd.</p></fieldset><div class="field"><label for="instructions">Aanvullende instructies</label><textarea id="instructions" name="instructions" maxlength="4000" aria-describedby="instructions-hint instructions-error">${esc(p.instructions)}</textarea><span class="hint" id="instructions-hint">Verplicht bij Eigen methode. Geeft geen toestemming voor workoutwijzigingen of publicatie.</span><span class="field-error" id="instructions-error"></span></div><div class="actions"><button type="submit" class="primary">Wijzigingen bekijken</button><button type="button" id="save-draft">Concept opslaan</button></div><div id="review"></div><p class="status-line" id="profile-status" role="status"></p></form></section><aside class="stack"><section class="card"><h2>Wat gebeurt er bij activeren?</h2><ul><li>Nieuwe adviezen gebruiken je actieve voorkeuren.</li><li>Oude rapporten blijven herleidbaar.</li><li>Een opgeslagen concept heeft nog geen invloed.</li><li>Workouts en openbare teksten hebben hun eigen goedkeuring.</li></ul></section><section class="card"><h2>Doelen en context</h2><p>Doelen en bevestigde voorkeuren worden afzonderlijk beheerd. Agenda-afspraken blijven in hun eigen bron.</p><p class="hint">In dit ontwerpvoorbeeld wijzig je alleen het coachprofiel. De volledige velden staan in de live instellingen.</p></section></aside></div>`;
}
const pages={today,training,health,insight,data,settings};
function render(focus=false) {
  const page=location.hash.slice(1)||'today';
  main.innerHTML=(pages[page]||today)();
  document.title=`${({today:'Dag',training:'Activiteit',health:'Gezondheid',insight:'Inzicht',data:'Gegevens',settings:'Coach'})[page]||'Dag'} · VibeSynergy ontwerp`;
  const current=page==='data'?'settings':page;
  for(const a of document.querySelectorAll('nav a, header > a[href="#settings"]')) {if(a.hash===`#${current}`)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}
  document.querySelector('[data-refresh]')?.addEventListener('click',()=>{scenario.value='ready';render();document.querySelector('[data-refresh]').focus();});
  document.querySelector('#zone-metric')?.addEventListener('change',e=>{model.metric=e.target.value;const p=document.querySelector('#zone-metric').closest('section');const holder=document.createElement('div');holder.innerHTML=zonePanel();p.replaceWith(holder.firstElementChild);bindZone();});
  document.querySelector('[data-note]')?.addEventListener('click',()=>document.querySelector('#note-status').textContent='Voorbeeld bevestigd; niets opgeslagen in VibeSynergy.');
  for(const b of document.querySelectorAll('[data-source]')) b.addEventListener('click',()=>document.querySelector('#source-status').textContent='Voorbeeld vernieuwd. De andere bron houdt zijn eigen verbindingsstatus.');
  document.querySelector('[data-reconnect]')?.addEventListener('click',()=>document.querySelector('#source-status').textContent='In VibeSynergy opent hier de aanmelding voor uitsluitend deze bron. Dit prototype maakt geen verbinding.');
  bindForm(); if(focus)main.focus();
}
function bindZone(){document.querySelector('#zone-metric')?.addEventListener('change',e=>{model.metric=e.target.value;const section=e.target.closest('section');const holder=document.createElement('div');holder.innerHTML=zonePanel();section.replaceWith(holder.firstElementChild);bindZone();document.querySelector('#zone-metric').focus();});}
function bindForm(){
  const form=document.querySelector('#coach-form');if(!form)return;
  function payload(){return Object.fromEntries(new FormData(form));}
  function validate(p){const error=p.method==='custom'&&!p.instructions.trim();document.querySelector('#instructions-error').textContent=error?'Beschrijf je eigen trainingsmethode.':'';document.querySelector('#instructions').setAttribute('aria-invalid',String(error));document.querySelector('#instructions').setAttribute('aria-describedby','instructions-hint instructions-error');document.querySelector('#form-errors').innerHTML=error?'<div class="notice error" tabindex="-1"><strong>Controleer je invoer</strong><p><a href="#instructions">Beschrijf je eigen trainingsmethode.</a></p></div>':'';if(error)document.querySelector('#form-errors a').addEventListener('click',e=>{e.preventDefault();document.querySelector('#instructions').focus();});if(error)document.querySelector('#form-errors>div').focus();return !error;}
  form.addEventListener('input',()=>{document.querySelector('#review').innerHTML='';});
  form.addEventListener('submit',e=>{e.preventDefault();const p=payload();if(!validate(p))return;const old=model.active;document.querySelector('#review').innerHTML=`<div class="review"><h3>Je voorgestelde aanpak</h3><ul>${['method','athlete','priority'].map(k=>`<li>${old?esc(names[old[k]]):'Niet ingesteld'} → <strong>${esc(names[p[k]])}</strong></li>`).join('')}</ul><p>${p.instructions?esc(p.instructions):'Geen aanvullende instructies.'}</p><p class="hint">Dit activeert alleen het fictieve profiel in deze pagina.</p><button type="button" class="primary" id="activate">Dit voorbeeldprofiel activeren</button></div>`;document.querySelector('#activate').addEventListener('click',()=>{model.active=p;model.draft=p;model.revision++;render();document.querySelector('#profile-status').textContent='Voorbeeldprofiel actief. VibeSynergy-instellingen zijn niet veranderd.';document.querySelector('#profile-status').setAttribute('tabindex','-1');document.querySelector('#profile-status').focus();});});
  document.querySelector('#save-draft').addEventListener('click',()=>{const p=payload();if(!validate(p))return;model.draft=p;model.revision++;render();document.querySelector('#profile-status').textContent='Concept opgeslagen in dit voorbeeld; nog niet geactiveerd.';});
}
scenario.addEventListener('change',()=>render());
document.querySelector('#theme').addEventListener('click',e=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';e.target.setAttribute('aria-pressed',String(dark));e.target.textContent=dark?'Licht thema':'Donker thema';});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();});
document.querySelector('#menu').addEventListener('click',e=>e.target.setAttribute('aria-expanded',String(e.target.getAttribute('aria-expanded')!=='true')));
window.addEventListener('hashchange',()=>{document.querySelector('#menu').setAttribute('aria-expanded','false');render(true);});render();
